def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    mine = []
    opp = []
    for a, b in history:
        mine.append(a)
        opp.append(b)

    if n == 1:
        return 'D' if opp[0] == 'D' else 'C'

    rem = 100 - n

    if rem > 3 and opp[-1] == 'D' and mine[-1] == 'C':
        start = n - 7
        if start < 0:
            start = 0
        recent_d = False
        for j in range(start, n):
            if mine[j] == 'D':
                recent_d = True
                break
        if not recent_d:
            return 'D'

    opp_c = 0
    for b in opp:
        if b == 'C':
            opp_c += 1

    trans_n = [0.0, 0.0, 0.0, 0.0]
    trans_c = [0.0, 0.0, 0.0, 0.0]

    recent_start = n - 25
    if recent_start < 1:
        recent_start = 1

    for i in range(1, n):
        w = 2.0 if i >= recent_start else 1.0
        prev_my = mine[i - 1]
        prev_opp = opp[i - 1]
        s = (1 if prev_my == 'D' else 0) * 2 + (1 if prev_opp == 'D' else 0)
        trans_n[s] += w
        if opp[i] == 'C':
            trans_c[s] += w

    g = (opp_c + 2.0) / (n + 4.0)
    if g < 0.0:
        g = 0.0
    elif g > 1.0:
        g = 1.0

    prior = [
        0.88 + 0.07 * g,
        0.55 + 0.30 * g,
        0.05 + 0.06 * g,
        0.05 + 0.05 * g,
    ]
    alpha = [3.0, 2.0, 1.0, 1.0]

    pC = [0.0, 0.0, 0.0, 0.0]
    for s in range(4):
        p = (trans_c[s] + alpha[s] * prior[s]) / (trans_n[s] + alpha[s])
        if p < 0.0:
            p = 0.0
        elif p > 1.0:
            p = 1.0
        pC[s] = p

    hz = rem if rem < 30 else 30
    vals = [[0.0, 0.0, 0.0, 0.0]]

    for k in range(1, hz + 1):
        prev = vals[-1]
        curr = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            p = pC[s]
            q = 1.0 - p
            if k == 1:
                vc = 3.0 * p
                vd = 1.0 + 4.0 * p
            else:
                vc = 3.0 * p + p * prev[0] + q * prev[1]
                vd = 5.0 * p + q + p * prev[2] + q * prev[3]
            if vd > vc + 1e-9:
                curr[s] = vd
            else:
                curr[s] = vc
        vals.append(curr)

    terminal = vals[hz - 1]
    cur = (1 if mine[-1] == 'D' else 0) * 2 + (1 if opp[-1] == 'D' else 0)
    p = pC[cur]
    q = 1.0 - p

    vc = 3.0 * p + p * terminal[0] + q * terminal[1]
    vd = 5.0 * p + q + p * terminal[2] + q * terminal[3]

    if vd > vc + 1e-9:
        return 'D'
    return 'C'
